import {COMPARE_LIMIT,STATE_KEY,initialState,readState,writeState,migrateState,modelCount,quantity,filterProducts,isExact,comparisonKeys,comparisonStatus,differs,visiblePair,selectPair,toggleComparison,moveComparison,addComparison,replaceComparison,removeComparison,undoComparison,cartTotal,cartCount,quantityLabel,addCartItem,listText as exportList,consultationText,validRoute,isGroup,normalizeGroup,catalogCategory} from './logic.js';

// Project/lab UI is not needed to open a comparison. Shared state rules above
// stay synchronous; the existing UI and its CSS load on their first real use.
const sciencePages=new Set(['projects','project','templates','lab','model-map']);
let scienceModule=null,scienceLoad=null,modalInteractionEpoch=0;
function loadScience(){
 return scienceLoad??=import('./science-entry.js').then(module=>(scienceModule=module));
}
function sciencePlaceholder(failed=false){
 return `<section data-science-loading role="status"><h1>${failed?'Не вдалося відкрити розділ':'Завантажуємо розділ…'}</h1><p>Збережені проєкти й чернетки не змінено.</p>${failed?'<button class="btn secondary" data-action="load-science">Оновити сторінку й повторити</button>':''}<p><a href="${href(route.brand,'catalog')}">До каталогу</a> · <a href="${href('ng','documents')}">Документи</a></p></section>`;
}
function mountSciencePage(){
 const epoch=modernMountEpoch,hash=route.hash,source=state;
 loadScience().then(()=>{if(epoch===modernMountEpoch&&hash===route.hash&&source===state)render(false);}).catch(()=>{
  if(epoch===modernMountEpoch&&hash===route.hash&&source===state){const main=$('#main');if(main)main.innerHTML=sciencePlaceholder(true);}
 });
}
function handleScience(action,dataset,source,helpers){
 if(!action?.startsWith('science-')&&action!=='comparison-save-to-project')return false;
 if(scienceModule)return scienceModule.handleScience(action,dataset,source,helpers);
 const epoch=modernMountEpoch,modalEpoch=++modalInteractionEpoch,request=structuredClone(dataset);
 loadScience().then(module=>{
  // A late import must not replace a newer dialog, route, state or request.
  if(epoch===modernMountEpoch&&modalEpoch===modalInteractionEpoch&&source===state)module.handleScience(action,request,source,helpers);
 }).catch(()=>{if(epoch===modernMountEpoch&&modalEpoch===modalInteractionEpoch&&source===state)toast('Не вдалося завантажити проєкти. Дані не змінено. Відкрийте «Мої проєкти», щоб безпечно повторити завантаження.');});
 return true;
}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',cart:'<path d="M3 4h2l2 12h11l3-9H6M9 21h.01M18 21h.01"/>',heart:'<path d="M20.8 4.8a5.5 5.5 0 0 0-7.8 0L12 5.9l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.4a5.5 5.5 0 0 0 0-7.8Z"/>',compare:'<path d="M5 20V10M12 20V4M19 20V7M3 20h18"/>',battery:'<rect x="3" y="6" width="17" height="12" rx="2"/><path d="M23 10v4M8 12h7M11.5 8.5v7"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(1 0) scale(.9)"/>',network:'<rect x="7" y="2" width="10" height="6" rx="1"/><rect x="2" y="16" width="7" height="5" rx="1"/><rect x="15" y="16" width="7" height="5" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',cable:'<path d="M7 2v5a5 5 0 0 0 10 0V2M12 12v5a4 4 0 0 1-8 0v-2M5 2h4M15 2h4M2 15h4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v6h5M8 12h8M8 16h8"/>',check:'<path d="m5 12 4 4L20 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
Object.assign(icons,{
 expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>',
 collapse:'<path d="M3 8h5V3M21 8h-5V3M8 21v-5H3M16 21v-5h5"/>',
 wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M9 16a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r="1"/>',
 splitter:'<path d="M2 12h7M15 5h7M15 12h7M15 19h7M9 12l6-7M9 12h6M9 12l6 7"/><rect x="7" y="8" width="5" height="8" rx="1"/>',
 meter:'<rect x="5" y="3" width="14" height="19" rx="2"/><rect x="8" y="7" width="8" height="6" rx="1"/><path d="M10 3V1M14 3V1M9 17h1M14 17h1"/>',
 plug:'<rect x="5" y="7" width="14" height="11" rx="2"/><path d="M9 7V2M15 7V2M12 18v4M10 11h4l-3 4"/>'
});
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const KEY=STATE_KEY;const withScience=s=>({...s,science:normalizeScience(s.science)});const initial=()=>withScience(initialState());
let storage=caseContext.storage;if(!caseContext.active)try{storage=window.localStorage;}catch{}
const loaded=readState(storage);
let modernWorkbench=null,modernMountEpoch=0,modernWorkbenchModule;
let removedCandidate=null,pickerReplace='',pickerQuery='',modalFocusKey='',restoringResearch=false,researchScrollController;
let state=withScience(loaded.state),storageOk=caseContext.active?storage.status.persisted:loaded.status==='ok',storageStatus=loaded.status,route,toastTimer,returnFocus,synchronizing=false;
if(caseContext.active)caseContext.getState=()=>state;
const saveLabel=()=>caseContext.active?caseSaveLabel(storage.status):(storageOk?'Збережено в цьому браузері.':'Лише в пам’яті сторінки. Збережіть експорт.');
function save(){if(synchronizing)return true;storageOk=writeState(storage,state);storageStatus=storageOk?(state.recovery?'recovery':'ok'):'denied';const w=$('#storage-warning');if(w){w.hidden=storageOk&&storageStatus==='ok';w.innerHTML=storageMessage();}document.querySelectorAll('[data-save-status]').forEach(el=>{const text=saveLabel();if(el.textContent!==text)el.textContent=text;});return storageOk;}

function storageMessage(){
 const recovery=state?.recovery?'Частина попередніх даних потребує відновлення. Початковий запис доступний для експорту.<button data-action="download-recovery">Завантажити копію</button>':'';
 const denied=caseContext.active&&!storageOk?caseStorageMessage(storage.status):!storageOk?'Збереження в браузері недоступне. Нові зміни лише в пам’яті сторінки; перед перезавантаженням або закриттям збережіть копію. <button data-action="export-live-state">Копія поточного стану (JSON)</button>':'';
 return [recovery,denied].filter(Boolean).join(' ');
}
const compareIds=()=>state.compareByGroup[normalizeGroup(state.view.group)];
const compareCount=()=>Object.values(state.compareByGroup).reduce((n,ids)=>n+ids.length,0);
const isCompared=p=>state.compareByGroup[p.group].includes(p.id);
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200);}
const total=()=>cartTotal(state.cart),qty=()=>cartCount(state.cart);
function href(brand,page='catalog',id='',params={}){const q=new URLSearchParams(params);return `#/${brand}/${page}${id?'/'+id:''}${q.size?'?'+q:''}`;}
function catalogLink(brand=route.brand){return state.catalogs[brand]||href(brand);}
function productLink(p,brand=route.brand){return href(brand==='ng'&&!p.ng?'asp':brand,'product',p.id);}
function parse(){const hash=location.hash||'#/asp/catalog';const [path,query='']=hash.slice(1).split('?');const [_,brand,page,id]=path.split('/');return {hash,brand:brand==='ng'?'ng':'asp',page:validRoute(hash)?page:'missing',id,params:new URLSearchParams(query)};}
function go(url){if(location.hash===url)render();else location.hash=url;}
function logo(brand){return brand==='asp'?`<span class="brand-logo"><span class="emblem"><img src="${assetUrl('assets/asp24-original.webp')}" alt="Емблема ASP24"></span><span class="wordmark">ASP<span>24</span><small>КАТАЛОГ ОБЛАДНАННЯ</small></span></span>`:`<span class="brand-logo"><img class="ngmark" src="${assetUrl('assets/ng-original.svg')}" alt="Емблема NG"><span class="wordmark ng">NG <b>Group</b><small>ТЕХНІЧНІ РІШЕННЯ</small></span></span>`;}
function header(){
 if(route.page==='compare')return researchHeader();
 if(['checkout','orders','order'].includes(route.page))return orderHeader();
 const b=route.brand,ng=b==='ng',q=['catalog','documents'].includes(route.page)?route.params.get('q')||'':'';
 let asp=href('asp'),nghref=href('ng');
 if(['product','document'].includes(route.page)&&byId(route.id)){asp=href('asp','product',route.id);nghref=byId(route.id).ng?href('ng',route.page,route.id):href('ng');}
 const active=page=>route.page===page||(page==='projects'&&route.page==='project')||(page==='catalog'&&['product','model-map'].includes(route.page))||(page==='documents'&&route.page==='document');
 const sections=[['catalog',ng?'Технічний каталог':'Каталог'],['projects','Мої проєкти'],['templates','Сценарії'],['lab','Довідник'],...(ng?[['documents','Документи'],['partners','Партнерам'],['service','Сервіс']]:[])];
 return `<header class="mast"><div class="topline"><a class="project" href="${href(b)}">ASP24 / NG Group</a><div class="demo-tag"><span>Демо · умовні товари</span><button class="text-btn" data-action="about">Про демо</button></div></div><div class="brandnav"><a href="${href(b)}" aria-label="${ng?'NG Group':'ASP24'} — каталог">${logo(b)}</a><nav class="brand-switch" aria-label="Розділи прототипу"><a class="${!ng?'active':''}" href="${asp}" ${!ng?'aria-current="true"':''}>ASP24</a><a class="${ng?'active':''}" href="${nghref}" ${ng?'aria-current="true"':''}>NG Group</a></nav><form id="search-form" class="searchbar" role="search"><input id="search" name="q" aria-label="Пошук за моделлю, артикулом чи виробником" placeholder="Модель, артикул або виробник" value="${esc(q)}"><button aria-label="Знайти">${icon('search')}</button></form><nav class="header-actions" aria-label="Мій вибір"><a href="${href(b,'compare')}">${icon('compare')}<span>Порівняння</span><span class="count">${compareCount()}</span></a><a href="${href(b,'favorites')}">${icon('heart')}<span>Обране</span><span class="count">${state.favorites.length}</span></a><a href="${href('asp','cart')}">${icon('cart')}<span>Кошик</span><span class="count">${qty()}</span></a><a href="${href('asp','orders')}" class="orders-nav">${icon('file')}<span>Замовлення</span><span class="count">${state.orders.length}</span></a></nav></div></header><nav class="subnav" aria-label="Основна навігація"><div class="subnav-inner">${sections.map(([page,label])=>`<a href="${page==='catalog'?catalogLink():href(b,page)}" class="${active(page)?'active':''}" ${active(page)?'aria-current="page"':''}>${label}</a>`).join('')}</div></nav><div id="storage-warning" class="storage-warning" ${storageOk&&storageStatus==='ok'?'hidden':''}>${storageMessage()}</div>`;
}
function footer(){return `<footer class="footer"><span>Демонстрація інтерфейсу. Товари й ціни умовні; замовлення та звернення не надсилаються. Не вводьте особистих даних.</span><div><button data-action="reports">Аналітичні огляди</button> · <button data-action="about">Про демонстрацію</button></div></footer>`;}
function addCart(id){const p=byId(id);if(!p)return false;const result=addCartItem(state,id);if(result!=='ok'){toast(result==='limit'?'Максимум — 999 одиниць.':`${p.name}: немає в наявності. Модель не додано.`);return false;}save();render(false);toast(`${p.name} · ${p.sku}: додано ${quantityLabel(p,1)}`);return true;}
function toggleCompare(id){if(toggleComparison(state,id)==='limit'){state.view.group=byId(id).group;save();picker('',byId(id).sku);return;}save();render(false);}
function compareButton(p){const on=isCompared(p);return `<button class="compare-toggle ${on?'selected':''}" data-action="compare" data-id="${p.id}" aria-pressed="${on}" aria-label="${on?'Прибрати з порівняння':'Порівняти'} ${esc(p.name)}">${icon('compare')}<span>${on?'Додано':'Порівняти'}</span></button>`;}
function favoriteButton(p){const on=state.favorites.includes(p.id);return `<button class="favorite ${on?'selected':''}" data-action="favorite" data-id="${p.id}" aria-pressed="${on}" aria-label="${on?'Прибрати з обраного':'В обране'} ${esc(p.name)}">${icon('heart')}</button>`;}
function cartButton(p,full=false){return `<button class="btn ${full?'full':''}" data-action="cart" data-id="${p.id}" ${!p.available?'disabled':''}>${p.available?`${icon('cart')}${state.cart[p.id]?'Додати ще 1':'До кошика'}`:'До кошика'}</button>`;}
function cableLength(p){return Number(p.packageLengthM??parseFloat(p.props['Довжина бухти']))||0;}
function categoryArtwork(p,detail=false){
 return `<span class="category-pictogram" ${detail?`role="img" aria-label="Ілюстрація типу: ${esc(groups[p.group].name)}"`:'aria-hidden="true"'}>${icon(groups[p.group].icon)}</span>`;
}
function productCard(p,exact=false){const ng=route.brand==='ng',keys=highlights[p.group];return `<article class="product" data-product-id="${p.id}"><div class="product-top">${route.page!=='catalog'||catalogCategory(route.params)==='all'?`<span class="tag">${groups[p.group].name}</span>`:''}${favoriteButton(p)}</div><div class="product-body">${exact?'<span class="exact">Точний збіг</span>':''}<h3><a href="${productLink(p)}">${readable(p.name)}</a></h3><p class="mono sku">${p.sku}</p><dl class="key-specs">${keys.map(k=>`<div><dt>${k}</dt><dd>${readable(display(p.props[k]))}</dd></div>`).join('')}</dl></div><a class="model-display" href="${productLink(p)}" tabindex="-1" aria-hidden="true">${categoryArtwork(p)}</a><div class="product-foot">${ng?`<div class="offer"><span class="muted" style="font-size:13px">${p.ng?'Виконання '+p.revision+' · технічний опис':'Комерційна картка · ASP24'}</span></div><div class="card-buttons"><a class="btn secondary" href="${productLink(p)}">${p.ng?'Технічна картка':'Картка ASP24'} ${icon('arrow')}</a>${compareButton(p)}</div>`:`<div class="offer"><div class="price">${money(p.price)}<span class="unit">за ${p.group==='cable'?'бухту '+cableLength(p)+' м':p.unit}</span></div><span class="stock ${p.available?'':'no'}">${p.available?'В наявності':'Немає в наявності'}</span></div><div class="card-buttons">${cartButton(p)}${compareButton(p)}<button class="project-mini" data-action="comparison-save-to-project" data-ids="${p.id}">У проєкт</button></div>`}</div></article>`;}
function getFiltered(){return filterProducts(route.brand,route.params);}
function catalog(){return renderCatalog({route,state,productCard,compareButton,favoriteButton,cartButton,icon,empty,dock});}

function empty(title,desc,label,action){return `<div class="empty">${icon('search')}<h2 style="margin-top:16px">${title}</h2><p>${desc}</p><button class="btn" data-action="${action}">${label}</button></div>`;}
function dock(){const ids=compareIds();if(!compareCount())return '';return `<div class="compare-dock"><div><strong>${groups[state.view.group].name}: ${ids.length} із ${COMPARE_LIMIT}</strong><p>${modelCount(compareCount())} у збережених групах</p></div><a class="btn" href="${href(route.brand,'compare')}">Порівняти ${icon('arrow')}</a></div>`;}
function specRows(p){return groups[p.group].keys.map(k=>`<tr><th scope="row">${k}</th><td class="${p.props[k]===null?'no-data':''}">${readable(display(p.props[k]))}</td></tr>`).join('');}
function details(p){const ng=route.brand==='ng',keys=highlights[p.group];return `<a class="back" href="${catalogLink()}">${icon('back')}Назад до добору</a><div class="detail-grid"><section><div class="detail-head"><div class="eyebrow">${groups[p.group].name}</div><h1>${readable(p.name)}</h1><span class="mono">${p.sku} · виконання ${p.revision}</span><p>${p.desc}</p></div><dl class="detail-stats">${keys.map(k=>`<div><dt>${k}</dt><dd>${readable(display(p.props[k]))}</dd></div>`).join('')}</dl><div class="detail-art">${categoryArtwork(p,true)}<span>Ілюстрація категорії · не фото моделі</span></div><div class="notice"><b>Перед підключенням</b>${p.compat}</div><div class="details"><details><summary>Усі технічні параметри</summary><div class="details-content"><table class="spec-table"><tbody>${specRows(p)}</tbody></table><p style="font-size:13px;margin-top:12px">«Не уточнено» — даних немає.</p></div></details><details><summary>Відмінності виконань</summary><div class="details-content"><table style="margin-top:12px"><tbody>${products.filter(x=>x.group===p.group).map(x=>`<tr><th><a href="${productLink(x,ng&&!x.ng?'asp':route.brand)}">${x.name}</a></th><td>${groups[p.group].filters.map(k=>display(x.props[k])).join(' · ')}</td></tr>`).join('')}</tbody></table></div></details><details ${ng?'open':''}><summary>Документи для цієї моделі</summary><div class="details-content">${p.ng?`<a class="btn secondary" href="${href('ng','document',p.id)}">${icon('file')}Приклад технічного опису</a><p style="font-size:13px;margin-top:12px">Виконання D1 · українська. Демонстраційний документ.</p>`:`<p>Документа NG для цієї моделі немає.</p>`}</div></details></div></section><aside class="detail-panel">${ng?`<h2>Консультація та закупівля</h2><button class="btn full" data-action="consult" data-id="${p.id}">Запитати про цю модель</button><a class="btn secondary full" href="${productLink(p,'asp')}">Ця модель в ASP24 ${icon('arrow')}</a>`:`<div class="eyebrow">Ціна моделі</div><div class="price" style="margin-top:12px">${money(p.price)}<span class="unit">за ${p.group==='cable'?'бухту '+cableLength(p)+' м':p.unit}</span></div><p class="stock ${p.available?'':'no'}">${p.available?'В наявності':'Немає в наявності'}</p>${p.group==='cable'?'<p class="notice">Продаж бухтами по '+cableLength(p)+' м, без відрізання.</p>':''}${cartButton(p,true)}${state.cart[p.id]?`<p class="status-save">У вашому кошику: ${quantityLabel(p,state.cart[p.id])}</p>`:''}${p.ng?`<a class="btn secondary full" href="${productLink(p,'ng')}">Технічна картка NG Group ${icon('arrow')}</a>${!p.available?`<button class="btn secondary full" data-action="consult" data-id="${p.id}">Запитати про цю модель</button>`:''}`:''}` }<div style="display:flex;align-items:center;gap:12px;border-top:1px solid var(--line);padding-top:18px;margin-top:22px">${compareButton(p)}${favoriteButton(p)}<span style="font-size:14px">Обране</span></div></aside></div>`;}
function researchHeader(){return `<header class="research-global"><a href="${catalogLink()}" aria-label="${route.brand==='asp'?'ASP24':'NG Group'} — каталог">${logo(route.brand)}</a><span>ASP24 / NG Group</span><button class="text-btn" data-action="about">Про демо</button></header><div id="storage-warning" class="storage-warning" ${storageOk&&storageStatus==='ok'?'hidden':''}>${storageMessage()}</div>`;}
function comparisonBack(){return compareCount()?`<a class="back return-comparison" href="${href(state.view.compareBrand,'compare','',state.view.compareExperience==='modern'?{experience:'modern'}:{})}">${icon('compare')}До порівняння</a>`:'';}
function modelHeading(p,slot){return `<div class="research-model" data-compare-id="${p.id}">${slot===undefined?`<button class="model-name" data-action="compare-details" data-id="${p.id}" aria-label="Докладніше: ${esc(p.name)}" title="${esc(p.name)}"><span class="model-name-text">${readable(p.name)}</span></button>`:`<button class="model-name pair-choice" data-action="choose-pair" data-slot="${slot}" data-id="${p.id}" aria-label="Обрати модель ${slot+1}: ${esc(p.name)}"><span class="model-name-text">${readable(p.name)}</span><span aria-hidden="true">⌄</span></button>`}<button class="remove-model" data-action="remove-compare" data-id="${p.id}" aria-label="Видалити ${esc(p.name)} з порівняння">×</button></div>`;}
function modelOffer(p,mobile=false){return `<div class="research-offer" ${mobile?`role="group" aria-label="${esc(p.name)}: умовна ціна та наявність"`:""}><strong class="money">${readable(money(p.price))} <span>/ ${p.unit}</span></strong><span class="stock ${p.available?'':'no'}">${p.available?'В наявності':'Немає в наявності'}</span>${mobile?`<button class="text-btn" data-action="compare-details" data-id="${p.id}" aria-label="Докладніше: ${esc(p.name)}"><span aria-hidden="true">⋯</span></button>`:''}</div>`;}
function comparisonOrder(ps){return `<ol class="order-list">${ps.map((p,i)=>`<li><span>${esc(p.name)}<small class="mono">${p.sku}</small></span><div class="compare-controls"><button data-action="move-compare" data-id="${p.id}" data-delta="-1" aria-label="Перемістити ${esc(p.name)} ліворуч" ${i===0?'disabled':''}>←</button><button data-action="move-compare" data-id="${p.id}" data-delta="1" aria-label="Перемістити ${esc(p.name)} праворуч" ${i===ps.length-1?'disabled':''}>→</button></div></li>`).join('')}</ol>`;}
function modernComparisonActive(){return route?.page==='compare'&&route.params.get('experience')==='modern';}
let restoringModernView=false;
// This SPA restores every route from view.pages. Native history scrolling can
// otherwise run before hashchange and overwrite the outgoing page's position.
if('scrollRestoration' in history)history.scrollRestoration='manual';
function modernSnapshot(){const reading=state.view.pages[route.hash]?.modern;return {tablePositions:reading?.group===state.view.group?reading:undefined,pairFocus:reading?.group===state.view.group&&reading.pairFocus,caseActive:caseContext.active,brand:route.brand,group:state.view.group,groups:Object.entries(groups).map(([id,g])=>({id,name:g.name,count:state.compareByGroup[id].length})),candidates:compareIds().map(byId),pair:visiblePair(compareIds(),state.view.pairs[state.view.group]),differences:state.view.differences,undoAvailable:!!removedCandidate,undoKind:removedCandidate?.replacementId?'replace':'remove',saveLabel:saveLabel(),storageWarning:storageMessage(),catalogHref:catalogLink(),legacyHref:href(route.brand,'compare'),cart:{...state.cart}};}
function updateModernWorkbench(){modernWorkbench?.update(modernSnapshot());}
function saveModernWorkbench(){captureView();const persisted=save();updateModernWorkbench();return persisted;}
function modernFallback(message,error=false){return `<p role="${error?'alert':'status'}">${message}</p><nav class="modal-actions" aria-label="Доступні розділи"><a class="btn secondary" href="${href(route.brand,'compare')}">Класичне порівняння</a><a class="btn secondary" href="${catalogLink()}">До каталогу</a><a class="btn secondary" href="${href('ng','documents')}">Документи моделей</a><a class="btn secondary" href="${assetUrl('index.html')}">HTML-огляди та PDF</a></nav>`;}
function mountModernWorkbench(){
 const element=$('#modern-comparison'),epoch=modernMountEpoch;if(!element)return;
 const readingView=state.view.pages[route.hash];restoringModernView=true;
 modernWorkbenchModule??=import('./src/ui/comparison-workbench.tsx');
 modernWorkbenchModule.then(({mountWorkbench})=>{
  if(epoch!==modernMountEpoch||!element.isConnected||!modernComparisonActive())return;
  state.view.compareBrand=route.brand;state.view.compareExperience='modern';
  modernWorkbench=mountWorkbench(element,modernSnapshot(),{
   search(query){return filterProducts('asp',new URLSearchParams({cat:state.view.group,q:query}));},
   add(id,replaceId=''){captureView();const undo=replaceId?replaceComparison(state,id,replaceId):null;const result=replaceId?(undo?'ok':'unknown'):addComparison(state,id);if(result!=='ok'){toast(result==='limit'?'Добір уже містить шість моделей. Оберіть кандидата для заміни.':'Модель уже додано або вона недоступна.');return false;}if(undo)removedCandidate=undo;saveModernWorkbench();return true;},
   remove(id){captureView();removedCandidate=removeComparison(state,id);saveModernWorkbench();},
   undo(){if(undoComparison(state,removedCandidate)){removedCandidate=null;saveModernWorkbench();return true;}toast('Немає місця для повернення. Поточний добір не змінено.');return false;},
   pair(slot,id){state.view.pairs[state.view.group]=selectPair(compareIds(),state.view.pairs[state.view.group],slot,id);saveModernWorkbench();},
   group(id){if(!isGroup(id))return;state.view.group=id;saveModernWorkbench();},
   differences(enabled){state.view.differences=enabled;saveModernWorkbench();},
   details(id){captureView();comparisonDetails(id);},
   cart(id){const result=addCartItem(state,id);if(result!=='ok'){toast(result==='limit'?'Максимум — 999 одиниць.':'Модель не додано: немає в наявності.');return false;}saveModernWorkbench();toast(`${byId(id).name}: додано ${quantityLabel(byId(id),1)}.`);return true;},
   shortlist(ids){handleScience('comparison-save-to-project',{ids,brand:route.brand},state,scienceHelpers());},
   save(){return saveModernWorkbench();}
  });
  const workspace=element.querySelector('.comparison-workbench');workspace.dataset.restoringView='true';
  requestAnimationFrame(()=>{
   if(epoch!==modernMountEpoch||!element.isConnected)return;
   if(readingView){
    element.querySelectorAll('details').forEach((item,index)=>{if(index<readingView.details.length)item.open=readingView.details[index];});
    if(readingView.modern?.group===state.view.group)for(const variant of ['full','pair']){const table=element.querySelector(`.wb-${variant}`),point=readingView.modern[variant];if(table&&point){table.scrollLeft=point.x;table.scrollTop=point.y;}}
    window.scrollTo(0,readingView.scroll);
    let target;try{target=readingView.focus?.startsWith('summary:')?element.querySelectorAll('summary')[Number(readingView.focus.split(':')[1])]:readingView.focus?[...element.querySelectorAll(readingView.focus)].find(item=>item.getClientRects().length):null;}catch{}target?.focus({preventScroll:true});
   }
   requestAnimationFrame(()=>{if(epoch===modernMountEpoch&&element.isConnected){delete workspace.dataset.restoringView;restoringModernView=false;}});
  });
 }).catch(()=>{if(epoch===modernMountEpoch&&element.isConnected){restoringModernView=false;element.innerHTML=modernFallback('Не вдалося завантажити робочий простір. Поточний добір не змінено.',true);}});
}
function comparePage(){
  const groupId=normalizeGroup(state.view.group),ids=compareIds(),ps=ids.map(byId),only=state.view.differences,pair=visiblePair(ids,state.view.pairs[groupId]).map(byId),keys=comparisonKeys(ps,only&&ps.length>1),pairKeys=comparisonKeys(pair,only&&pair.length>1);
  state.view.compareBrand=route.brand;state.view.compareExperience='classic';
  const parameter=(k,models)=>{const status=comparisonStatus(models,k);return `<span>${esc(k)}</span>${status.different?'<small class="difference-label">Відмінність</small>':''}${status.incomplete?'<small class="incomplete-label">Неповні дані</small>':''}`;};
  return `<section class="research-workspace" data-group="${groupId}" aria-label="Робоча область порівняння">
  <div class="research-toolbar"><a class="research-back" href="${catalogLink()}" aria-label="Повернутися до добору">${icon('back')}<span>До добору</span></a><h1>Порівняння</h1><label class="sr-only" for="compare-group">Група порівняння</label><select id="compare-group">${Object.entries(groups).map(([g,v])=>`<option value="${g}" ${g===groupId?'selected':''}>${v.name} · ${state.compareByGroup[g].length}</option>`).join('')}</select><span class="research-count"><span class="desktop-count">${ps.length} із 6</span><span class="mobile-count">${pair.length} з ${ps.length}</span></span><button class="btn add-candidate" data-action="add-compare-models">＋ Додати модель</button><button class="research-tool" data-action="saved-selection" aria-label="Збережений вибір">${icon('grid')}<span>Мій вибір</span></button><button class="research-tool expand-toggle" data-action="expand-compare" aria-pressed="${state.view.expanded}" aria-label="${state.view.expanded?'Повернути звичайний вигляд':'Розгорнути порівняння'}">${icon(state.view.expanded?'collapse':'expand')}<span>${state.view.expanded?'Повернути':'Розгорнути'}</span></button></div>
  <div class="research-modes"><label class="check"><input id="differences" type="checkbox" ${only?'checked':''}>Лише відмінності</label><span class="mode-description">${ps.length===1?'Одна модель · додайте другу':only?'Відомі відмінності й неповні дані':'Усі параметри'}</span><button class="research-project" data-action="comparison-save-to-project" data-ids="${ids.join(',')}" ${!ids.length?'disabled':''}>У проєкт</button><button class="text-btn" data-action="order-models" ${!ps.length?'disabled':''}>Порядок моделей</button><a class="text-btn" href="${href(route.brand,'compare','',{experience:'modern'})}">Новий робочий простір →</a></div>
  ${!ps.length?`<div class="research-empty"><h2>Оберіть першу модель</h2><p>${groups[groupId].name} · до 6 кандидатів</p><button class="btn" data-action="add-compare-models">Додати модель</button></div>`:`
  <div class="research-desktop" role="table" aria-label="Порівняння: ${groups[groupId].name}" aria-colcount="${ps.length+1}" style="--model-count:${ps.length};--table-min:${200+ps.length*210}px">
    <div class="research-context"><div class="research-head-scroll"><div class="research-grid research-head" role="row"><div class="parameter-cell" role="columnheader">Параметр</div>${ps.map(p=>`<div role="columnheader">${modelHeading(p)}</div>`).join('')}</div></div></div>
    <div class="research-scroll" tabindex="0" role="rowgroup" aria-label="Параметри моделей; прокручування по горизонталі"><div class="research-grid research-offers" role="row"><div class="parameter-cell" role="rowheader">Ціна / наявність</div>${ps.map(p=>`<div role="cell">${modelOffer(p)}</div>`).join('')}</div>${keys.map(k=>`<div class="research-grid research-row ${differs(ps,k)?'different':'same'}" role="row" data-row="${esc(k)}"><div class="parameter-cell" role="rowheader">${parameter(k,ps)}</div>${ps.map(p=>`<div role="cell" class="${p.props[k]==null?'no-data':''}">${readable(display(p.props[k]))}</div>`).join('')}</div>`).join('')}</div>
    ${!keys.length?'<p class="research-no-difference">Відомих відмінностей і прогалин у технічних параметрах немає.</p>':''}
  </div>
  <div class="research-mobile"><div class="mobile-model-context" style="--pair-count:${pair.length}">${pair.map((p,i)=>modelHeading(p,i)).join('')}</div><div class="mobile-offers" style="--pair-count:${pair.length}">${pair.map(p=>modelOffer(p,true)).join('')}</div><dl class="research-pair" style="--pair-count:${pair.length}">${pairKeys.map(k=>`<div data-row="${esc(k)}" class="${differs(pair,k)?'different':'same'}"><dt>${parameter(k,pair)}</dt>${pair.map(p=>`<dd class="${p.props[k]==null?'no-data':''}"><span class="sr-only">${esc(p.name)}: </span>${readable(display(p.props[k]))}</dd>`).join('')}</div>`).join('')}</dl>${!pairKeys.length?'<p class="research-no-difference">Відомих відмінностей і прогалин у технічних параметрах пари немає.</p>':''}</div>
  <div class="research-foot"><span>«Не уточнено» — даних немає.</span><span data-save-status role="status" aria-live="polite">${saveLabel()}</span></div>`}</section>`;
}
function picker(replaceId='',query='',preserveFocus=false){
  pickerReplace=replaceId;pickerQuery=query;
  const ids=compareIds(),group=state.view.group,ps=products.filter(p=>p.group===group),found=filterProducts('asp',new URLSearchParams({cat:group,q:query}));
  const content=modalTitle(replaceId?'Замінити модель':'Додати модель')+`<p class="picker-context">${groups[group].name} · ${ids.length} із ${COMPARE_LIMIT}${replaceId?` · замість ${esc(byId(replaceId).name)}`:''}</p>${ids.length===COMPARE_LIMIT&&!replaceId?`<div class="notice">У доборі вже 6 моделей. Оберіть, кого замінити; поточний склад не зміниться без вашого вибору.</div><label class="field">Замінити<select id="replace-target"><option value="">Оберіть модель</option>${ids.map(id=>`<option value="${id}">${esc(byId(id).name)}</option>`).join('')}</select></label>`:''}<label class="field">Пошук у групі<input id="candidate-search" type="search" value="${esc(query)}" placeholder="Назва або артикул" autocomplete="off"></label><div class="candidate-list" aria-live="polite">${candidateRows(found,ids,replaceId)}</div><p class="picker-note">${ps.every(p=>ids.includes(p.id))?'Усі моделі цієї демонстраційної групи вже додано.':''}</p>`;
  openModal(content);if(!preserveFocus)$('#candidate-search')?.focus();
}
function candidateRows(ps,ids,replaceId){return ps.length?ps.map(p=>`<article class="candidate" data-candidate="${p.id}"><div><h3>${esc(p.name)}</h3><p class="mono">${p.sku}</p><p>${highlights[p.group].map(k=>display(p.props[k])).join(' · ')}</p><span class="stock ${p.available?'':'no'}">${p.available?'В наявності':'Немає в наявності'}</span></div><button class="btn secondary" data-action="pick-candidate" data-id="${p.id}" ${ids.includes(p.id)?'disabled':''}>${ids.includes(p.id)?'Додано':replaceId?'Замінити':'Додати'}</button></article>`).join(''):'<p class="notice">За цим запитом моделей немає.</p>';}
function finishCandidate(id){
  captureView();const modernReplace=modernComparisonActive()&&pickerReplace,undo=modernReplace?replaceComparison(state,id,pickerReplace):null;
  const result=modernReplace?(undo?'ok':'unknown'):addComparison(state,id,pickerReplace);
  if(result==='limit'){picker();return;}if(result!=='ok'){toast(result==='exists'?'Ця модель вже у порівнянні.':'Модель не знайдено.');return;}
  if(undo){removedCandidate=undo;save();closeModal();updateModernWorkbench();$('[data-testid="wb-undo"]')?.focus();toast(`${byId(undo.id).name} → ${byId(id).name}. Дію можна скасувати.`);return;}
  const old=pickerReplace;save();closeModal();render(false);focusModel(id);toast(old?`${byId(old).name} → ${byId(id).name}`:`${byId(id).name}: додано до порівняння.`);
}
function focusModel(id){const nodes=[...document.querySelectorAll(`.model-name[data-id="${CSS.escape(id)}"]`)];const target=nodes.find(el=>el.getClientRects().length)||$('[data-action="add-compare-models"]');if(target&&matchMedia('(min-width:701px)').matches){const sc=$('.research-scroll'),box=$('.research-head-scroll'),r=target.getBoundingClientRect(),b=box?.getBoundingClientRect();if(sc&&b){if(r.right>b.right)sc.scrollLeft+=r.right-b.right+12;else if(r.left<b.left+200)sc.scrollLeft-=b.left+212-r.left;}}target?.focus({preventScroll:true});}
function choosePair(slot){const ids=compareIds(),pair=visiblePair(ids,state.view.pairs[state.view.group]),other=pair[slot===0?1:0];openModal(modalTitle(`Модель ${slot+1} із ${ids.length}`)+`<p class="picker-context">Інша сторона: ${esc(byId(other)?.name||'ще не обрана')}</p><div class="pair-options">${ids.map(id=>{const p=byId(id);return `<button data-action="select-pair" data-slot="${slot}" data-id="${id}" ${pair[slot]===id?'disabled':''}><span>${esc(p.name)}<small class="mono">${p.sku}</small></span><span>${pair[slot]===id?'Обрано':other===id?'Обміняти сторони':'Обрати'}</span></button>`;}).join('')}</div><button class="btn secondary full" data-action="add-compare-models">Додати модель</button>`);}
